      "claim": "Mandating pre-deployment reviews creates a stagnation tax that grants only the largest firms the right to innovate.",
      "targets": ["AN-27"]
    },
    {
      "claim": "Decentralized, verifiable safety systems are more robust against cascades than centralized, brittle regulatory mandates.",
      "targets": ["AN-25"]
    },
    {
      "claim": "We must implement a 5% infrastructure dividend tax on automated profits to fund universal reskilling.",
      "targets": ["AN-9"]
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Automated interpretability tools can generate sufficiently reliable quantified risk estimates for AI systems.",
      "if_wrong": "The accountability (market) mechanism would fail to internalize costs accurately, potentially allowing dangerous systems to operate without sufficient liability."
    },
    {
      "assumption": "Open-weight proliferation effectively democratizes cognitive access and prevents monopolistic control.",
      "if_wrong": "The competitive market for AI would remain highly concentrated, and open-source development would fail to provide a meaningful alternative to corporate-owned models."
